/* Minimal register subset for this platform check, from ST RM0090 and PM0214.
 * SPI1/PB0 acquire BMP388 data. Only USB uses HSE/PLL; no HAL or RTOS.
 * Keep these definitions private until the platform libraries are integrated.
 */
#define REG32(address) (*(volatile uint32_t *)(uintptr_t)(address))
#define REG8(address)  (*(volatile uint8_t *)(uintptr_t)(address))

#define RCC_CR          REG32(0x40023800U)
#define RCC_PLLCFGR     REG32(0x40023804U)
#define RCC_AHB2RSTR    REG32(0x40023814U)
#define RCC_AHB2ENR     REG32(0x40023834U)
#define RCC_CFGR        REG32(0x40023808U)
#define RCC_APB1RSTR    REG32(0x40023820U)
#define RCC_APB1ENR     REG32(0x40023840U)
#define RCC_AHB1ENR     REG32(0x40023830U)
#define RCC_APB2RSTR    REG32(0x40023824U)
#define RCC_APB2ENR     REG32(0x40023844U)
#define RCC_GPIOAB_BITS ((1U << 0) | (1U << 1))
#define RCC_SPI1_BIT    (1U << 12)
#define RCC_CR_HSION    (1U << 0)
#define RCC_CR_HSIRDY   (1U << 1)
#define RCC_CFGR_SW     (3U << 0)
#define RCC_CFGR_SWS    (3U << 2)
#define RCC_CFGR_HPRE   (15U << 4)
#define RCC_CFGR_PPRE1  (7U << 10)
#define RCC_CFGR_PPRE2  (7U << 13)
#define RCC_TIM2_BIT    (1U << 0)
#define RCC_TIM5_BIT    (1U << 3)
#define RCC_SYSCFG_BIT  (1U << 14)

#define SYSCFG_EXTICR1  REG32(0x40013808U)
#define EXTI_IMR        REG32(0x40013C00U)
#define EXTI_RTSR       REG32(0x40013C08U)
#define EXTI_FTSR       REG32(0x40013C0CU)
#define EXTI_PR         REG32(0x40013C14U)
#define EXTI0_BIT       (1U << 0)
#define EXTI0_IRQ_BIT   (1U << 6)
#define NVIC_EXTI0_IPR  REG8(0xE000E406U)

#define GPIOA_MODER     REG32(0x40020000U)
#define GPIOA_OTYPER    REG32(0x40020004U)
#define GPIOA_OSPEEDR   REG32(0x40020008U)
#define GPIOA_PUPDR     REG32(0x4002000CU)
#define GPIOA_BSRR      REG32(0x40020018U)
#define GPIOA_AFRL      REG32(0x40020020U)
#define GPIOA_AFRH      REG32(0x40020024U)
#define GPIOB_MODER     REG32(0x40020400U)
#define GPIOB_PUPDR     REG32(0x4002040CU)
#define BMP388_CS_HIGH  (1U << 4)
#define BMP388_CS_LOW   (1U << 20)

#define SPI1_CR1        REG32(0x40013000U)
#define SPI1_CR2        REG32(0x40013004U)
#define SPI1_SR         REG32(0x40013008U)
#define SPI1_DR8        REG8(0x4001300CU)
#define SPI_CR1_MSTR    (1U << 2)
#define SPI_CR1_DIV16   (3U << 3)
#define SPI_CR1_SPE     (1U << 6)
#define SPI_CR1_SSI     (1U << 8)
#define SPI_CR1_SSM     (1U << 9)
#define SPI_SR_RXNE     (1U << 0)
#define SPI_SR_TXE      (1U << 1)
#define SPI_SR_BSY      (1U << 7)
#define SPI_SR_ERRORS  ((1U << 5) | (1U << 6) | (1U << 8)) /* MODF/OVR/FRE */
#define SPI_WAIT_LIMIT  10000U /* Bounded iterations, not calibrated time. */

#define TIM2_CR1        REG32(0x40000000U)
#define TIM2_DIER       REG32(0x4000000CU)
#define TIM2_SR         REG32(0x40000010U)
#define TIM2_EGR        REG32(0x40000014U)
#define TIM2_CNT        REG32(0x40000024U)
#define TIM2_PSC        REG32(0x40000028U)
#define TIM2_ARR        REG32(0x4000002CU)
#define TIM5_CR1        REG32(0x40000C00U)
#define TIM5_SR         REG32(0x40000C10U)
#define TIM5_EGR        REG32(0x40000C14U)
#define TIM5_CNT        REG32(0x40000C24U)
#define TIM5_PSC        REG32(0x40000C28U)
#define TIM5_ARR        REG32(0x40000C2CU)
#define TIM_CR1_CEN     (1U << 0)
#define TIM_CR1_ARPE    (1U << 7)
#define TIM_DIER_UIE    (1U << 0)
#define TIM_SR_UIF      (1U << 0)
#define TIM_EGR_UG      (1U << 0)

#define SCB_VTOR        REG32(0xE000ED08U)
#define SCB_CPACR       REG32(0xE000ED88U)
#define SCB_CPACR_FPU   (15U << 20)
#define DBGMCU_CR       REG32(0xE0042004U)
#define DBGMCU_APB1_FZ  REG32(0xE0042008U)
#define DBG_SLEEP       (1U << 0)
#define DBG_TIM2_STOP   (1U << 0)
#define DBG_TIM5_STOP   (1U << 3)

/* TIM2 is external IRQ 28: ISER0/ICER0/ICPR0 and byte IPR[28]. */
#define TIM2_IRQ_NUMBER 28U
#define TIM2_IRQ_BIT    (1U << TIM2_IRQ_NUMBER)
#define NVIC_ISER0      REG32(0xE000E100U)
#define NVIC_ICER0      REG32(0xE000E180U)
#define NVIC_ICPR0      REG32(0xE000E280U)
#define NVIC_TIM2_IPR   REG8(0xE000E400U + TIM2_IRQ_NUMBER)

/* This is a bounded iteration count, not a calibrated time interval. */
#define CLOCK_WAIT_LIMIT 1000000U
#define TIM2_COUNTER_HZ 2000000U

_Static_assert(PLATFORM_HSI_HZ % TIM2_COUNTER_HZ == 0U,
               "TIM2 prescaler must be integral");
_Static_assert(TIM2_COUNTER_HZ % PLATFORM_TIMER_HZ == 0U,
               "TIM2 period must be integral");

extern const uint32_t g_pfnVectors[];

uint32_t SystemCoreClock = PLATFORM_HSI_HZ;
volatile uint32_t g_platform_ready;
volatile uint32_t g_platform_error;
volatile uint32_t g_tim2_irq_count;
volatile uint32_t g_main_wake_count;

/* ST startup calls this BEFORE .data/.bss initialization.
 * Only registers and the link-time vector address may be used here.
 */
void SystemInit(void)
{
    SCB_CPACR |= SCB_CPACR_FPU;
    SCB_VTOR = (uint32_t)(uintptr_t)g_pfnVectors;
    __asm volatile ("dsb 0xF\n\tisb 0xF" ::: "memory");
}

static void Platform_Stop(uint32_t error)
{
    __asm volatile ("cpsid i" ::: "memory");
    g_platform_ready = 0U;
    g_platform_error = error;
    for (;;) {
        __asm volatile ("nop");
    }
}

static void Platform_ClockInit(void)
{
    uint32_t remaining = CLOCK_WAIT_LIMIT;

    RCC_CR |= RCC_CR_HSION;
    while ((RCC_CR & RCC_CR_HSIRDY) == 0U) {
        if (--remaining == 0U) {
            Platform_Stop(PLATFORM_ERROR_HSI_TIMEOUT);
        }
    }

    /* Switch to HSI before removing bus dividers. Do not depend on HSE/PLL. */
    RCC_CFGR &= ~RCC_CFGR_SW;
    remaining = CLOCK_WAIT_LIMIT;
    while ((RCC_CFGR & RCC_CFGR_SWS) != 0U) {
        if (--remaining == 0U) {
            Platform_Stop(PLATFORM_ERROR_CLOCK_SWITCH_TIMEOUT);
        }
    }
    RCC_CFGR &= ~(RCC_CFGR_HPRE | RCC_CFGR_PPRE1 | RCC_CFGR_PPRE2);
    SystemCoreClock = PLATFORM_HSI_HZ;
    /* HCLK = PCLK1 = PCLK2 = 16 MHz nominal. APB1 divider is 1,
     * so TIM2 gets PCLK1 directly (no timer clock doubling).
     */
}

static void Platform_TimerInit(void)
{
    NVIC_ICER0 = TIM2_IRQ_BIT;
    RCC_APB1ENR |= RCC_TIM2_BIT | RCC_TIM5_BIT;
    (void)RCC_APB1ENR; /* Read back to allow the peripheral clock to settle. */
    RCC_APB1RSTR |= RCC_TIM2_BIT;
    RCC_APB1RSTR &= ~RCC_TIM2_BIT;
    RCC_APB1RSTR |= RCC_TIM5_BIT;
    RCC_APB1RSTR &= ~RCC_TIM5_BIT;

    /* Keep SWD accessible during WFI sleep; freeze TIM2 while core is halted. */
    DBGMCU_CR |= DBG_SLEEP;
    DBGMCU_APB1_FZ |= DBG_TIM2_STOP | DBG_TIM5_STOP;

    TIM5_PSC = PLATFORM_HSI_HZ / 1000000U - 1U;
    TIM5_ARR = UINT32_MAX;
    TIM5_CNT = 0U;
    TIM5_EGR = TIM_EGR_UG;
    TIM5_SR = 0U;
    TIM5_CR1 = TIM_CR1_CEN;

    TIM2_CR1 = TIM_CR1_ARPE;
    TIM2_DIER = 0U;
    TIM2_PSC = PLATFORM_HSI_HZ / TIM2_COUNTER_HZ - 1U; /* 7 */
    TIM2_ARR = TIM2_COUNTER_HZ / PLATFORM_TIMER_HZ - 1U; /* 1999 */
    TIM2_CNT = 0U;
    TIM2_EGR = TIM_EGR_UG; /* Load buffered PSC/ARR before starting. */
    TIM2_SR = 0U; /* Discard the update flag generated by UG. */
    NVIC_ICPR0 = TIM2_IRQ_BIT;
    NVIC_TIM2_IPR = 0xF0U; /* Lowest priority: 15, four implemented bits. */
    TIM2_DIER = TIM_DIER_UIE;
    NVIC_ISER0 = TIM2_IRQ_BIT;
    TIM2_CR1 |= TIM_CR1_CEN;
}

static void Platform_SPI_Reset(void)
{
    RCC_APB2RSTR |= RCC_SPI1_BIT;
    RCC_APB2RSTR &= ~RCC_SPI1_BIT;
    SPI1_CR2 = 0U; /* Polling, no DMA or SPI interrupts. */
    /* Mode 0, MSB first, 8 bits, full duplex, software NSS kept high.
     * PCLK2 = 16 MHz; divider 16 gives SCK = 1 MHz nominal.
     */
    SPI1_CR1 = SPI_CR1_MSTR | SPI_CR1_DIV16 | SPI_CR1_SSI | SPI_CR1_SSM;
    SPI1_CR1 |= SPI_CR1_SPE;
}

static void Platform_SPI_Init(void)
{
    RCC_AHB1ENR |= RCC_GPIOAB_BITS;
    (void)RCC_AHB1ENR;
    /* Preload CS high BEFORE making PA4 an output. Preserve SWD PA13/PA14. */
    GPIOA_BSRR = BMP388_CS_HIGH;
    GPIOA_OTYPER &= ~(0xFU << 4);
    GPIOA_OSPEEDR = (GPIOA_OSPEEDR & ~(0xFFU << 8)) | (0x55U << 8);
    /* CS pull-up, MISO weak pull-down for a defined disconnected input.
     * SCK/MOSI have no pull; the module's actual external pulls are unchanged.
     */
    GPIOA_PUPDR = (GPIOA_PUPDR & ~(0xFFU << 8)) | (1U << 8) | (2U << 12);
    GPIOA_AFRL = (GPIOA_AFRL & ~(0xFFFU << 20)) | (0x555U << 20);
    /* PA4 GPIO output; PA5/PA6/PA7 AF5 = SPI1 SCK/MISO/MOSI. */
    GPIOA_MODER = (GPIOA_MODER & ~(0xFFU << 8)) | (0xA9U << 8);
    /* PB0: input, weak pull-down; sensor INT is configured push-pull/high. */
    GPIOB_MODER &= ~3U;
    GPIOB_PUPDR = (GPIOB_PUPDR & ~3U) | 2U;
    RCC_APB2ENR |= RCC_SPI1_BIT;
    (void)RCC_APB2ENR;
    Platform_SPI_Reset();
}

uint32_t Platform_TimeUs(void)
{
    return TIM5_CNT;
}

uint32_t Platform_USB_Init(void)
{
    uint32_t remaining = CLOCK_WAIT_LIMIT;
    /* HCLK/PCLK/TIM clocks stay at HSI 16 MHz. PLL is USB-only.
     * Reference schematic Y2: 8 MHz. M=8, N=192, Q=4 -> USB 48 MHz.
     */
    RCC_CR &= ~(1U << 24);
    while ((RCC_CR & (1U << 25)) != 0U) {
        if (--remaining == 0U) return 2U;
    }
    RCC_CR |= 1U << 16;
    remaining = CLOCK_WAIT_LIMIT;
    while ((RCC_CR & (1U << 17)) == 0U) {
        if (--remaining == 0U) return 1U;
    }
    RCC_PLLCFGR = 8U | (192U << 6) | (1U << 16) | (1U << 22) | (4U << 24);
    RCC_CR |= 1U << 24;
    remaining = CLOCK_WAIT_LIMIT;
    while ((RCC_CR & (1U << 25)) == 0U) {
        if (--remaining == 0U) return 3U;
    }
    RCC_AHB1ENR |= 1U;
    (void)RCC_AHB1ENR;
    GPIOA_OTYPER &= ~((1U << 11) | (1U << 12));
    GPIOA_PUPDR &= ~(0xFU << 22);
    GPIOA_OSPEEDR |= 0xFU << 22;
    GPIOA_AFRH = (GPIOA_AFRH & ~((0xFU << 12) | (0xFU << 16))) |
                  (10U << 12) | (10U << 16);
    GPIOA_MODER = (GPIOA_MODER & ~(0xFU << 22)) | (0xAU << 22);
    RCC_AHB2ENR |= 1U << 7;
    (void)RCC_AHB2ENR;
    RCC_AHB2RSTR |= 1U << 7;
    RCC_AHB2RSTR &= ~(1U << 7);
    /* Bus-powered board: PA9 is not wired to VBUS in the reference schematic.
     * Disable VBUS sensing; only USB powers the board during USB operation.
     */
    REG32(0x50000038U) = (1U << 21);
    return 0U;
}

static void Platform_DataReadyInit(void)
{
    NVIC_ICER0 = EXTI0_IRQ_BIT;
    RCC_APB2ENR |= RCC_SYSCFG_BIT;
    (void)RCC_APB2ENR;
    EXTI_IMR &= ~EXTI0_BIT;
    SYSCFG_EXTICR1 = (SYSCFG_EXTICR1 & ~0xFU) | 1U; /* EXTI0 <- PB0 */
    EXTI_FTSR &= ~EXTI0_BIT;
    EXTI_RTSR |= EXTI0_BIT;
    EXTI_PR = EXTI0_BIT;
    NVIC_ICPR0 = EXTI0_IRQ_BIT;
    NVIC_EXTI0_IPR = 0x80U; /* Priority 8, above the TIM2 heartbeat (15). */
    NVIC_ISER0 = EXTI0_IRQ_BIT;
    EXTI_IMR |= EXTI0_BIT;
}

static bmp388_result_t Platform_SPI_Wait(uint32_t mask, uint32_t expected)
{
    for (uint32_t remaining = SPI_WAIT_LIMIT; remaining != 0U; --remaining) {
        const uint32_t status = SPI1_SR;
        if ((status & SPI_SR_ERRORS) != 0U) {
            return BMP388_SPI_ERROR;
        }
        if ((status & mask) == expected) {
            return BMP388_OK;
        }
    }
    return BMP388_SPI_TIMEOUT;
}

static bmp388_result_t Platform_SPI_Byte(uint8_t tx, uint8_t *rx)
{
    bmp388_result_t result = Platform_SPI_Wait(SPI_SR_TXE, SPI_SR_TXE);
    if (result != BMP388_OK) {
        return result;
    }
    SPI1_DR8 = tx;
    result = Platform_SPI_Wait(SPI_SR_RXNE, SPI_SR_RXNE);
    if (result == BMP388_OK) {
        *rx = SPI1_DR8;
    }
    return result;
}

static bmp388_result_t Platform_SPI_End(bmp388_result_t result)
{
    if (result == BMP388_OK) {
        result = Platform_SPI_Wait(SPI_SR_TXE, SPI_SR_TXE);
    }
    if (result == BMP388_OK) {
        result = Platform_SPI_Wait(SPI_SR_BSY, 0U);
    }
    if (result != BMP388_OK) {
        SPI1_CR1 &= ~SPI_CR1_SPE;
    }
    GPIOA_BSRR = BMP388_CS_HIGH;
    if (result != BMP388_OK) {
        Platform_SPI_Reset();
    }
    return result;
}

static bmp388_result_t Platform_SPI_Write(uint8_t reg, uint8_t value)
{
    uint8_t discard;
    if (reg > 0x7FU) {
        return BMP388_INVALID_ARGUMENT;
    }
    GPIOA_BSRR = BMP388_CS_LOW;
    bmp388_result_t result = Platform_SPI_Byte(reg, &discard); /* bit 7 = write */
    if (result == BMP388_OK) {
        result = Platform_SPI_Byte(value, &discard);
    }
    return Platform_SPI_End(result);
}

static bmp388_result_t Platform_SPI_Read(uint8_t reg, uint8_t *data, uint32_t length)
{
    uint8_t discard;
    bmp388_result_t result;

    if (data == NULL || length == 0U || reg > 0x7FU) {
        return BMP388_INVALID_ARGUMENT;
    }
    GPIOA_BSRR = BMP388_CS_LOW;
    result = Platform_SPI_Byte((uint8_t)(reg | 0x80U), &discard);
    /* BMP388 requires a dummy byte AFTER the address, before valid data. */
    if (result == BMP388_OK) {
        result = Platform_SPI_Byte(0U, &discard);
    }
    for (uint32_t i = 0U; i < length && result == BMP388_OK; ++i) {
        result = Platform_SPI_Byte(0U, &data[i]);
    }
    return Platform_SPI_End(result);
}

void EXTI0_IRQHandler(void)
{
    if ((EXTI_PR & EXTI0_BIT) != 0U) {
        EXTI_PR = EXTI0_BIT;
        Application_DataReadyISR(Platform_TimeUs());
        __asm volatile ("dsb 0xF" ::: "memory");
    }
}

void TIM2_IRQHandler(void)
{
    if ((TIM2_SR & TIM_SR_UIF) != 0U) {
        /* UIF clears by writing zero; preserve any other status flags. */
        TIM2_SR = ~TIM_SR_UIF;
        ++g_tim2_irq_count;
        __asm volatile ("dsb 0xF" ::: "memory");
    }
}

void HardFault_Handler(void)
{
    Platform_Stop(PLATFORM_ERROR_HARDFAULT);
}

int main(void)
{
    __asm volatile ("cpsid i" ::: "memory");
    Platform_ClockInit();
    Platform_TimerInit();
    Platform_SPI_Init();
    Platform_DataReadyInit();
    Application_Init(Platform_SPI_Read, Platform_SPI_Write, g_tim2_irq_count);
    g_platform_ready = 1U;
    __asm volatile ("cpsie i" ::: "memory");
    SerialOutput_Init();

    for (;;) {
        __asm volatile ("dsb 0xF\n\twfi" ::: "memory");
        /* Evidence that main resumes after sleep, not a precision timebase.
         * Debugger wakeups can make this differ from the IRQ count.
         */
        ++g_main_wake_count;
        Application_Poll(g_tim2_irq_count);
        SerialOutput_Poll();
    }
}
